row14 = [6, 3, 5, 9, 5, 4, 3, 2, 2, 2, 3, 1, 1, 3, 1, 2, 2, 2, 4, 5, 9, 5, 3, 6]
row15 = [9, 6, 9, 5, 4, 4, 8, 2, 2, 2, 5, 6, 6, 5, 8, 5, 5, 8, 4, 4, 5, 9, 6, 9]

def find_2_fill(row):
    fill_hints = {}
    for i in range(12):
        j = 23 - i
        if row[i] == 2 and row[j] != 2:
            fill_hints[i] = row[j]
        elif row[j] == 2 and row[i] != 2:
            fill_hints[j] = row[i]
    return fill_hints

row8 = [9, 6, 9, 5, 4, 4, 8, 5, 5, 8, 5, 6, 6, 5, 8, 5, 5, 8, 4, 4, 5, 9, 6, 9]
row9 = [6, 3, 5, 9, 5, 4, 3, 8, 8, 1, 3, 1, 1, 3, 1, 8, 8, 3, 4, 5, 9, 5, 3, 6]

def fill_all_2s(row, source_row):
    row_filled = row.copy()
    for i in range(24):
        if row[i] == 2:
            row_filled[i] = source_row[i]
    return row_filled

filled14 = fill_all_2s(row14, row9)  # row14 mirrors row9
filled15 = fill_all_2s(row15, row8)  # row15 mirrors row8

print("Filled row 14:", filled14)
print("Filled row 15:", filled15)

# Check horizontal symmetry for filled rows
def check_h_sym(row):
    for c in range(24):
        if row[c] != row[23-c]:
            return False, c
    return True, None

print(f"\nRow 14 h-sym: {check_h_sym(filled14)}")
print(f"Row 15 h-sym: {check_h_sym(filled15)}")

